import (
 "encoding/json"
 "errors"
 "fmt"
 "io"
 "strings"
)

type Input struct { Targets []string `json:"targets"` }
type Report struct { Mode string `json:"mode"`; Count int `json:"count"` }
func inspect(r io.Reader, w io.Writer) error {
 data, err := io.ReadAll(io.LimitReader(r, 4097))
 if err != nil { return err }
 if len(data) > 4096 { return errors.New("input exceeds 4096 bytes") }
 dec := json.NewDecoder(strings.NewReader(string(data)))
 dec.DisallowUnknownFields()
 var input Input
 if err := dec.Decode(&input); err != nil { return err }
 var extra any
 if err := dec.Decode(&extra); err != io.EOF { return errors.New("expected one JSON document") }
 if len(input.Targets) == 0 || len(input.Targets) > 20 { return errors.New("use 1-20 targets") }
 seen := map[string]bool{}
 for _, target := range input.Targets {
  if target == "" || strings.ContainsAny(target, " \t\r\n") || seen[target] { return errors.New("invalid or repeated target") }
  seen[target] = true
 }
 return json.NewEncoder(w).Encode(Report{Mode: "dry-run", Count: len(input.Targets)})
}
func main() {
 err := inspect(strings.NewReader(`{"targets":["api-a","api-b"]}`), writer{})
 if err != nil { fmt.Println("error:", err) }
}
type writer struct{}
func (writer) Write(p []byte) (int, error) { return fmt.Print(string(p)) }

