import (
 "errors"
 "fmt"
)
var ErrConflict = errors.New("observed version changed")
type State struct { Version, Replicas int }
type Change struct { ExpectedVersion, Replicas int }
func plan(desired int, observed State) (*Change, error) {
 if desired < 0 || desired > 20 { return nil, errors.New("replicas outside budget") }
 if observed.Replicas == desired { return nil, nil }
 return &Change{ExpectedVersion: observed.Version, Replicas: desired}, nil
}
func apply(state *State, change Change) error {
 if state.Version != change.ExpectedVersion { return ErrConflict }
 state.Replicas = change.Replicas
 state.Version++
 return nil
}
func main() {
 state := State{Version: 41, Replicas: 2}
 change, _ := plan(3, state)
 fmt.Println("planned", change.ExpectedVersion, change.Replicas)
 fmt.Println("applied", apply(&state, *change), state)
 fmt.Println("stale", errors.Is(apply(&state, *change), ErrConflict))
 again, _ := plan(3, state)
 fmt.Println("converged", again == nil)
}

