import (
 "crypto/sha256"
 "encoding/hex"
 "errors"
 "fmt"
)
type Evidence struct { Digest string; Tests, Vet, VulnerabilityCheck bool }
func promote(artifact []byte, evidence Evidence, approvedDigest string) error {
 actual := sha256.Sum256(artifact)
 digest := hex.EncodeToString(actual[:])
 if len(approvedDigest) != 64 || digest != approvedDigest || evidence.Digest != approvedDigest { return errors.New("artifact identity mismatch") }
 if !evidence.Tests || !evidence.Vet || !evidence.VulnerabilityCheck { return errors.New("required gate failed") }
 return nil
}
func main() {
 artifact := []byte("reviewed release artifact")
 hash := sha256.Sum256(artifact)
 digest := hex.EncodeToString(hash[:])
 evidence := Evidence{Digest: digest, Tests: true, Vet: true, VulnerabilityCheck: true}
 fmt.Println("approved", promote(artifact, evidence, digest))
 fmt.Println("changed", promote([]byte("rebuilt differently"), evidence, digest))
 evidence.Tests = false
 fmt.Println("failed gate", promote(artifact, evidence, digest))
}

