import (
 "errors"
 "fmt"
 "math"
)
type Window struct { Total, Bad uint64 }
func burn(w Window, target float64) (float64, error) {
 if math.IsNaN(target) || math.IsInf(target, 0) || target <= 0 || target >= 1 || w.Total == 0 || w.Bad > w.Total { return 0, errors.New("invalid or missing evidence") }
 return (float64(w.Bad) / float64(w.Total)) / (1 - target), nil
}
func page(long, short Window, target, threshold float64) (bool, error) {
 if math.IsNaN(threshold) || math.IsInf(threshold, 0) || threshold <= 0 { return false, errors.New("invalid threshold") }
 a, err := burn(long, target); if err != nil { return false, err }
 b, err := burn(short, target); if err != nil { return false, err }
 return a >= threshold && b >= threshold, nil
}
func main() {
 high := Window{Total: 10000, Bad: 200}
 rate, _ := burn(high, 0.999)
 alert, _ := page(high, high, 0.999, 14.4)
 recovered, _ := page(high, Window{Total: 1000}, 0.999, 14.4)
 _, missing := burn(Window{}, 0.999)
 fmt.Printf("burn %.1fx page %t recovered %t missing %t\n", rate, alert, recovered, missing != nil)
}

