import "fmt"

type Incident struct { CurrentSchema, OldReaderMin, OldReaderMax int; WritesSinceBackup bool }
func recoveryPlan(i Incident) string {
 if i.CurrentSchema < 1 || i.OldReaderMin < 1 || i.OldReaderMin > i.OldReaderMax { return "reject invalid compatibility evidence" }
 if i.CurrentSchema >= i.OldReaderMin && i.CurrentSchema <= i.OldReaderMax { return "candidate: roll back binary; verify route and outcomes" }
 if i.WritesSinceBackup { return "roll forward or restore separately and reconcile accepted writes" }
 return "rehearse isolated restore; do not overwrite the live writer"
}
func main() {
 fmt.Println(recoveryPlan(Incident{CurrentSchema: 2, OldReaderMin: 1, OldReaderMax: 2}))
 fmt.Println(recoveryPlan(Incident{CurrentSchema: 2, OldReaderMin: 1, OldReaderMax: 1, WritesSinceBackup: true}))
 fmt.Println(recoveryPlan(Incident{CurrentSchema: 2, OldReaderMin: 1, OldReaderMax: 1}))
}
